      { name: '成长会员', price: '¥299', unit: '/月 · 建议试点价', features: ['最多20个产品与批次', '双语选品册与询价跟进', '需求匹配与月度数据复盘'], note: '正式定价需访谈供应商后确认' },
      { name: '企业协同', price: '面议', unit: '按服务范围报价', features: ['多账号与多基地管理', '批次资料协同与服务转介', '专属客户成功与业务复盘'], note: '按企业规模与服务内容议定' }
